def partial_derivs_vec(fct, delta):
    nx, ny, nz = fct.shape
    deriv_x = zeros(fct.shape)
    deriv_y = zeros(fct.shape)
    deriv_z = zeros(fct.shape)

    # Compute interior points using central differences
    for i in range(1, nx-1):
        for j in range(1, ny-1):
            for k in range(1, nz-1):
                deriv_x[i, j, k] = (fct[i+1, j, k] - fct[i-1, j, k]) / (2.0 * delta)
                deriv_y[i, j, k] = (fct[i, j+1, k] - fct[i, j-1, k]) / (2.0 * delta)
                deriv_z[i, j, k] = (fct[i, j, k+1] - fct[i, j, k-1]) / (2.0 * delta)

    # Compute boundary points using one-sided differences
    # x-direction boundaries
    for j in range(ny):
        for k in range(nz):
            deriv_x[0, j, k] = (fct[1, j, k] - fct[0, j, k]) / delta  # left boundary
            deriv_x[nx-1, j, k] = (fct[nx-1, j, k] - fct[nx-2, j, k]) / delta  # right boundary

    # y-direction boundaries
    for i in range(nx):
        for k in range(nz):
            deriv_y[i, 0, k] = (fct[i, 1, k] - fct[i, 0, k]) / delta  # bottom boundary
            deriv_y[i, ny-1, k] = (fct[i, ny-1, k] - fct[i, ny-2, k]) / delta  # top boundary

    # z-direction boundaries
    for i in range(nx):
        for j in range(ny):
            deriv_z[i, j, 0] = (fct[i, j, 1] - fct[i, j, 0]) / delta  # front boundary
            deriv_z[i, j, nz-1] = (fct[i, j, nz-1] - fct[i, j, nz-2]) / delta  # back boundary

    return deriv_x, deriv_y, deriv_z
