def NURBS_2D(xi_1, xi_2, i_1, i_2, p_1, p_2, n_1, n_2, Xi_1, Xi_2, w):
    def NURBS_basis(xi, i, p, Xi, w):
        if p == 0:
            return np.array([t <= Xi[xi+1] and Xi[xi] <= t for t in Xi]).astype(float) * w[i]
        else:
            alpha = (Xi - Xi[xi]) / (Xi[xi+p+1] - Xi[xi])
            beta = (Xi[xi+p+2] - Xi) / (Xi[xi+p+2] - Xi[xi+1])
            return alpha * NURBS_basis(xi, i, p-1, Xi, w) + beta * NURBS_basis(xi, i+1, p-1, Xi, w)

    N_1 = NURBS_basis(xi_1, i_1, p_1, Xi_1, w)
    N_2 = NURBS_basis(xi_2, i_2, p_2, Xi_2, w)

    denominator = np.sum(N_1 * N_2)
    N = np.array([N_1, N_2]) / denominator if denominator!= 0 else np.array([0, 0])

    return N
