import numpy as np

def SpeciesGrowth(g, pref, Rs, alive):
    N, R = g.shape
    g_temp = np.zeros(N)
    r_temp = np.zeros(N, dtype=int)

    for i in range(N):
        if alive[i]:
            consumed_resource = -1
            for j in range(R):
                if pref[i, j] - 1 == consumed_resource:
                    consumed_resource = pref[i, j] - 1
                    break
            if consumed_resource!= -1 and Rs[consumed_resource] > 0:
                g_temp[i] = g[i, consumed_resource]
                r_temp[i] = consumed_resource + 1  # +1 to match 1-based indexing

    return g_temp, r_temp
