def SolveSchroedinger(y0, En, l, R):
    import numpy as np
    from scipy import integrate, optimize

    def Schroed_deriv(y, r, l, En):
        u, u_prime = y  # Unpack the y array into u and u_prime
        u_double_prime = (l * (l + 1) / r**2 - 2 * 1 / r - En) * u  # Calculate u'' using the given differential equation
        Schroed = [u_prime, u_double_prime]  # The derivative of y is [u', u'']
        return Schroed

    def integrand(r, y, l, En):
        return Schroed_deriv(y, r, l, En)

    def solve_ode(r, y0, l, En):
        result = integrate.odeint(integrand, y0, r, args=(l, En))
        return result[:, 0]  # Return the first component of the result, which is u(r)

    def normalize(u, R):
        # Apply Simpson's rule for numerical integration
        integral, _ = integrate.simps(u**2, R)
        return u / np.sqrt(integral)

    R_large = np.flip(R)  # Start integration from large r
    u0 = solve_ode(R_large, y0, l, En)
    ur = normalize(u0, R_large)

    return ur
